package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.Locale;
@Entity @Table(name="evidence_governance_level",uniqueConstraints={@UniqueConstraint(name="uk_evidence_level_code",columnNames={"agency_id","framework_version_id","normalized_code"}),@UniqueConstraint(name="uk_evidence_level_order",columnNames={"agency_id","framework_version_id","display_order"})})
public class EvidenceGovernanceLevel extends RspAuditedEntity{@Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=200)private String label;@Column(nullable=false,length=2000)private String description;@Column(name="reference_only",nullable=false)private boolean referenceOnly;@Column(name="display_order",nullable=false)private int displayOrder;protected EvidenceGovernanceLevel(){}public EvidenceGovernanceLevel(String agency,String framework,String code,String label,String description,int order){super(agency);frameworkVersionId=requiredText(framework,"frameworkVersionId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.label=requiredText(label,"label");this.description=requiredText(description,"description");referenceOnly=true;if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getCode(){return code;}public String getLabel(){return label;}public String getDescription(){return description;}public boolean isReferenceOnly(){return referenceOnly;}public int getDisplayOrder(){return displayOrder;}}
